package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class GroupMyResubmissionsIntegrationTest {
 ResubmissionRequestStoreIntegrationTest f;GroupMyResubmissionsStore store;
 @BeforeEach void setup(){f=new ResubmissionRequestStoreIntegrationTest();f.setup();store=new GroupMyResubmissionsStore(f.f.f.source,new GroupStore(f.f.f.source,Clock.systemUTC()));}
 GroupMyResubmissionsStore.Page list(String filter,UUID after,int limit){return store.list(f.f.group,f.f.space,f.f.author,after,limit,filter);}
 GroupMyResubmissionsStore.Row row(){return list("ALL",null,100).items().stream().filter(v->v.submissionId().equals(f.answer.submissionId())).findFirst().orElseThrow();}
 UUID task(){var task=f.f.parent.create(f.f.f.key()).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,f.f.study,task,f.f.f.owner,1,"OPEN",f.f.f.trace);return task;}
 @Test void absenceAndAllReadsAreContentFreeAndCreateNoEvents(){
  int before=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:GroupMyResubmissionsStore.FILTERS)assertTrue(list(filter,null,20).items().isEmpty());assertNull(f.get(f.f.author,false).request());assertEquals(before,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
  f.change(0,1,"PRIVATE REASON");var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(row());assertEquals(14,json.size());for(String key:List.of("authorId","score","reason","content","requestedBy","requestId","snapshot","description"))assertFalse(json.has(key));assertEquals("REQUESTED",row().requestState());assertEquals(1,row().requestVersion());assertEquals(1,row().requestedSubmissionVersion());assertNull(row().resolvedSubmissionVersion());
 }
 @Test void actorScopeExcludesPeerRequestsAndIncludesOwnerOwnRequests(){
  f.change(0,1,"MY REASON");UUID peer=f.f.f.ids.next();var other=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,peer,0,2,f.f.f.key(),"PEER ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,other.submissionId(),f.f.f.owner,0,new ResubmissionRequestInput("REQUEST","PEER REASON",1,2),f.f.f.trace);
  var own=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,0,2,f.f.f.key(),"OWNER ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,own.submissionId(),f.f.f.owner,0,new ResubmissionRequestInput("REQUEST","OWNER SELF REQUEST",1,2),f.f.f.trace);
  UUID unrequested=task();f.f.store.submit(f.f.group,f.f.space,f.f.study,unrequested,f.f.author,0,2,f.f.f.key(),"NO REQUEST",f.f.f.trace);
  assertEquals(List.of(f.answer.submissionId()),list("ALL",null,100).items().stream().map(GroupMyResubmissionsStore.Row::submissionId).toList());assertEquals(other.submissionId(),store.list(f.f.group,f.f.space,peer,null,20,"ALL").items().getFirst().submissionId());assertEquals(own.submissionId(),store.list(f.f.group,f.f.space,f.f.f.owner,null,20,"ALL").items().getFirst().submissionId());assertTrue(store.list(f.f.group,f.f.space,f.f.f.ids.next(),null,20,"ALL").items().isEmpty());
 }
 @Test void requestCorrectionCancellationAndNewAnswerResolutionKeepExactVersions(){
  f.change(0,1,"FIRST");f.change(1,1,"CORRECTED");assertEquals(2,row().requestVersion());f.cancel(2);assertEquals("CANCELLED",row().requestState());assertTrue(list("REQUESTED",null,20).items().isEmpty());assertEquals(1,list("CANCELLED",null,20).items().size());f.f.submit(f.f.f.key(),1,2,"AFTER CANCEL");assertEquals("CANCELLED",row().requestState());assertNull(row().resolvedSubmissionVersion());f.change(3,2,"NEW REQUEST");String key=f.f.f.key();f.f.submit(key,2,2,"RESOLVING ANSWER");assertEquals("RESOLVED",row().requestState());assertEquals(2,row().requestedSubmissionVersion());assertEquals(3L,row().resolvedSubmissionVersion());assertEquals(5,row().requestVersion());f.change(5,3,"REQUEST CURRENT AGAIN");assertFalse(f.f.submit(key,2,2,"RESOLVING ANSWER").applied());assertEquals("REQUESTED",row().requestState());assertEquals(6,row().requestVersion());assertEquals(3,row().requestedSubmissionVersion());assertNull(row().resolvedSubmissionVersion());
 }
 @Test void keysetFilteringPrecedesLimitAcrossAssignments(){
  f.change(0,1,"FIRST");for(int n=0;n<8;n++){UUID assignment=task();var answer=f.f.store.submit(f.f.group,f.f.space,f.f.study,assignment,f.f.author,0,2,f.f.f.key(),"ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,f.f.study,assignment,answer.submissionId(),f.f.f.owner,0,new ResubmissionRequestInput("REQUEST","REASON",1,2),f.f.f.trace);if(n%2==0)f.store.change(f.f.group,f.f.space,f.f.study,assignment,answer.submissionId(),f.f.f.owner,1,new ResubmissionRequestInput("CANCEL",null,0,0),f.f.f.trace);}
  assertEquals(9,list("ALL",null,100).items().size());assertEquals(5,list("REQUESTED",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("REQUESTED",after,2);seen.addAll(p.items().stream().map(GroupMyResubmissionsStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("REQUESTED",null,100).items().stream().map(GroupMyResubmissionsStore.Row::submissionId).toList(),seen);assertEquals(5,new HashSet<>(seen).size());
 }
 @Test void closedArchivedReadsKeepPendingRequestAndCreateNothing(){
  var saved=f.change(0,1,"PENDING");f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);assertEquals("CLOSED",row().assignmentState());assertEquals("REQUESTED",row().requestState());f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,3,"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);int before=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:GroupMyResubmissionsStore.FILTERS)list(filter,null,20);assertEquals("RETIRED",row().assignmentState());assertEquals(saved,f.get(f.f.author,false).request());assertEquals(before,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }
 @Test void invalidOrInconsistentRequestMetadataNeverAppearsPendingOrResolved(){
  var original=f.change(0,1,"PRIVATE");f.f.submit(f.f.f.key(),1,2,"RESOLVED");String saved=f.f.f.jdbc.queryForObject("SELECT snapshot::text FROM resubmission_request WHERE request_id=?",String.class,original.requestId());try{for(String expression:List.of("snapshot-'state'","jsonb_set(snapshot,'{state}','\"INVALID\"')","jsonb_set(snapshot,'{state}','\"REQUESTED\"')","jsonb_set(snapshot,'{state}','\"CANCELLED\"')")){f.f.f.jdbc.update("UPDATE resubmission_request SET snapshot="+expression+" WHERE request_id=?",original.requestId());assertEquals("UNAVAILABLE",row().requestState());assertEquals(1,list("UNAVAILABLE",null,20).items().size());assertTrue(list("REQUESTED",null,20).items().isEmpty());assertTrue(list("RESOLVED",null,20).items().isEmpty());}}finally{f.f.f.jdbc.update("UPDATE resubmission_request SET snapshot=?::jsonb WHERE request_id=?",saved,original.requestId());}
 }
 @Test void currentSharedAssignmentLabelsDoNotChangeOriginalAnswerBasis(){
  var original=f.change(0,1,"ORIGINAL");f.f.parent.store.metadata(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"NEW <script> TITLE","NEW INSTRUCTIONS",f.f.f.trace);assertEquals("NEW <script> TITLE",row().assignmentTitle());assertEquals(2,row().assignmentVersion());assertEquals(original,f.get(f.f.author,false).request());assertEquals(2,original.assignmentVersion());
 }
 @Test void groupSpacePendingEmptyAndQueryBoundsFailClosed(){
  f.status(404,()->store.list(f.f.f.ids.next(),f.f.space,f.f.author,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.f.ids.next(),f.f.author,null,20,"ALL"));var groups=new GroupStore(f.f.f.source,Clock.systemUTC());var pending=groups.request(f.f.f.owner,f.f.f.key(),"Pending private Group","",f.f.f.trace);var space=f.f.f.ids.next();f.status(404,()->store.list(pending.groupId(),space,f.f.author,null,20,"ALL"));groups.activate(pending.groupId(),f.f.f.owner,space,f.f.f.trace);assertTrue(store.list(pending.groupId(),space,f.f.author,null,20,"ALL").items().isEmpty());for(String filter:List.of("requested","CURRENT","","REQUESTED' OR TRUE--"))f.status(400,()->list(filter,null,20));for(int limit:List.of(0,101))f.status(400,()->list("ALL",null,limit));
 }
 @Test void atomicSubmissionResolutionAndReadUseOneStatementSnapshot()throws Exception{
  f.change(0,1,"PENDING");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var read=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();if(v.requestState().equals("REQUESTED")){assertEquals(v.version(),v.requestedSubmissionVersion());assertNull(v.resolvedSubmissionVersion());}else{assertEquals("RESOLVED",v.requestState());assertTrue(v.requestedSubmissionVersion()<v.resolvedSubmissionVersion());assertTrue(v.resolvedSubmissionVersion()<=v.version());}}return true;});var write=pool.submit(()->{barrier.await();return f.f.submit(f.f.f.key(),1,2,"NEW ANSWER");});assertTrue(read.get(20,TimeUnit.SECONDS));assertTrue(write.get(20,TimeUnit.SECONDS).applied());assertEquals("RESOLVED",row().requestState());}
 }

 UUID task(UUID study){var id=f.f.parent.store.create(f.f.group,f.f.space,study,f.f.f.owner,f.f.f.key(),"Shared task <script>","Instructions",f.f.f.trace).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,study,id,f.f.f.owner,1,"OPEN",f.f.f.trace);return id;}
 UUID requested(UUID study,UUID assignment,boolean cancel){var answer=f.f.store.submit(f.f.group,f.f.space,study,assignment,f.f.author,0,2,f.f.f.key(),"PRIVATE ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,study,assignment,answer.submissionId(),f.f.f.owner,0,new ResubmissionRequestInput("REQUEST","PRIVATE REASON",1,2),f.f.f.trace);if(cancel)f.store.change(f.f.group,f.f.space,study,assignment,answer.submissionId(),f.f.f.owner,1,new ResubmissionRequestInput("CANCEL",null,0,0),f.f.f.trace);return answer.submissionId();}
 @Test void allStudiesCurrentLabelsOriginalBasisArchivesAndNoCourseEvents(){
  f.change(0,1,"ORIGINAL PRIVATE");var b=f.f.parent.parent.create(f.f.f.key()).study();UUID id=task(b.studyId()),answer=requested(b.studyId(),id,false);task(b.studyId());f.f.parent.parent.store.metadata(f.f.group,f.f.space,b.studyId(),f.f.f.owner,1,"Current B <script>","Current",f.f.f.trace);f.f.parent.store.metadata(f.f.group,f.f.space,b.studyId(),id,f.f.f.owner,2,"Current task","New instructions",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,b.studyId(),f.f.f.owner,2,"RETIRED",f.f.f.trace);
  assertEquals(2,list("ALL",null,100).items().size());var v=list("ALL",null,100).items().stream().filter(x->x.submissionId().equals(answer)).findFirst().orElseThrow();assertEquals(b.studyId(),v.studyId());assertEquals("Current B <script>",v.studyTitle());assertEquals("RETIRED",v.studyState());assertEquals("Current task",v.assignmentTitle());assertEquals(2,v.assignmentVersion());assertEquals("REQUESTED",v.requestState());int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:GroupMyResubmissionsStore.FILTERS)list(filter,null,100);assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));assertEquals(0,f.f.f.jdbc.queryForObject("SELECT count(*) FROM group_course WHERE group_id=?",Integer.class,f.f.group));
 }
 @Test void filteredKeysetCrossesStudiesAndExcludesOtherAuthors(){
  f.change(0,1,"FIRST");var b=f.f.parent.parent.create(f.f.f.key()).study();for(int n=0;n<12;n++){UUID st=n%2==0?f.f.study:b.studyId(),id=task(st);requested(st,id,n%3==0);var peer=f.f.store.submit(f.f.group,f.f.space,st,id,f.f.f.ids.next(),0,2,f.f.f.key(),"PEER PRIVATE",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,st,id,peer.submissionId(),f.f.f.owner,0,new ResubmissionRequestInput("REQUEST","PEER REASON",1,2),f.f.f.trace);}
  assertEquals(13,list("ALL",null,100).items().size());assertEquals(9,list("REQUESTED",null,100).items().size());assertEquals(4,list("CANCELLED",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("REQUESTED",after,2);seen.addAll(p.items().stream().map(GroupMyResubmissionsStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("REQUESTED",null,100).items().stream().map(GroupMyResubmissionsStore.Row::submissionId).toList(),seen);assertEquals(9,new HashSet<>(seen).size());
 }
 @Test void sameActorRequestInAnotherGroupCannotLeakAcrossGroupSpace(){
  f.change(0,1,"MY GROUP");var other=new ResubmissionRequestStoreIntegrationTest();other.setup();var answer=other.f.store.submit(other.f.group,other.f.space,other.f.study,other.f.assignment,f.f.author,0,2,other.f.f.key(),"OTHER GROUP PRIVATE",other.f.f.trace).submission();other.store.change(other.f.group,other.f.space,other.f.study,other.f.assignment,answer.submissionId(),other.f.f.owner,0,new ResubmissionRequestInput("REQUEST","OTHER GROUP PRIVATE REASON",1,2),other.f.f.trace);assertEquals(1,list("ALL",null,100).items().size());assertTrue(list("ALL",null,100).items().stream().noneMatch(v->v.studyId().equals(other.f.study)));f.status(404,()->store.list(f.f.group,other.f.space,f.f.author,null,20,"ALL"));f.status(404,()->store.list(other.f.group,f.f.space,f.f.author,null,20,"ALL"));
 }
}
